create extension if not exists pgcrypto;
create type public.user_role as enum ('renter','owner','admin');
create type public.rental_type as enum ('hourly','daily');
create type public.booking_status as enum ('pending','accepted','rejected','payment_pending','confirmed','in_progress','completed','cancelled','disputed','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,role public.user_role not null default 'renter',full_name text,phone text,avatar_url text,created_at timestamptz not null default now());
create table public.listings(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,title text not null,description text,category text not null,subcategory text,brand text,model text,city text not null,price numeric(12,2) not null check(price>=0),currency text not null default 'PLN',rental_type public.rental_type not null,open_time time not null default '08:00',close_time time not null default '20:00',buffer_minutes int not null default 60 check(buffer_minutes>=0),grace_minutes int not null default 60 check(grace_minutes>=0),minimum_hours int not null default 1 check(minimum_hours>=1),deposit numeric(12,2) not null default 0,instant_booking boolean not null default false,active boolean not null default true,image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.bookings(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings(id),renter_id uuid references public.profiles(id),renter_name text not null,renter_email text not null,renter_phone text not null,start_at timestamptz not null,end_at timestamptz not null,units numeric(12,2) not null check(units>0),subtotal numeric(12,2) not null check(subtotal>=0),platform_fee numeric(12,2) not null default 0,owner_amount numeric(12,2) not null default 0,currency text not null default 'PLN',status public.booking_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_at>start_at));
create table public.reviews(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,reviewer_id uuid not null references public.profiles(id),listing_id uuid not null references public.listings(id),rating int not null check(rating between 1 and 5),body text,created_at timestamptz not null default now(),unique(booking_id,reviewer_id));
create table public.messages(id uuid primary key default gen_random_uuid(),booking_id uuid references public.bookings(id) on delete cascade,sender_id uuid not null references public.profiles(id),recipient_id uuid not null references public.profiles(id),body text not null,created_at timestamptz not null default now());
create table public.ai_leads(id uuid primary key default gen_random_uuid(),source_url text,business_name text,contact_email text,contact_phone text,city text,category text,source_type text,score numeric(5,2),status text not null default 'new',created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.listings enable row level security;alter table public.bookings enable row level security;alter table public.reviews enable row level security;alter table public.messages enable row level security;alter table public.ai_leads enable row level security;
create policy "public active listings" on public.listings for select to anon,authenticated using(active=true);
create policy "owner inserts own listings" on public.listings for insert to authenticated with check(owner_id=auth.uid());
create policy "owner updates own listings" on public.listings for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "user reads own profile" on public.profiles for select to authenticated using(id=auth.uid());
create policy "user updates own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "renter creates booking" on public.bookings for insert to authenticated with check(renter_id=auth.uid());
create policy "participants read booking" on public.bookings for select to authenticated using(renter_id=auth.uid() or exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=auth.uid()));
create policy "owner updates booking" on public.bookings for update to authenticated using(exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=auth.uid()));
create policy "participants read messages" on public.messages for select to authenticated using(sender_id=auth.uid() or recipient_id=auth.uid());
create policy "user sends messages" on public.messages for insert to authenticated with check(sender_id=auth.uid());
create policy "public reads reviews" on public.reviews for select to anon,authenticated using(true);
create policy "reviewer creates review" on public.reviews for insert to authenticated with check(reviewer_id=auth.uid());
insert into public.listings(owner_id,title,category,brand,model,city,price,currency,rental_type) select id,'Seed listing','Cars','BMW','Demo','Warsaw',100,'PLN','daily' from public.profiles where false;
